&lt;/div&gt;&lt;div style=&quot;background-color: #fff; float: right; padding: 0 0 8px 8px&quot;&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Traits_raciaux_standards_5&quot;&gt;Traits raciaux standards&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Traits_raciaux_alternatifs_6&quot;&gt;Traits raciaux alternatifs&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Bonus_alternatifs_de_classe_de_pr&#233;dilection_7&quot;&gt;Bonus alternatifs de classe de pr&#233;dilection&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Nouvelles_r&#232;gles_raciales_8&quot;&gt;Nouvelles r&#232;gles raciales&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_0&quot;&gt;Dons&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Arch&#233;types_de_classes_1&quot;&gt;Arch&#233;types de classes&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#D&#233;couvertes_dalchimiste_2&quot;&gt;D&#233;couvertes d&#39;alchimiste&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#&#201;quipement_3&quot;&gt;&#201;quipement&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Sorts_4&quot;&gt;Sorts&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;&lt;i&gt;Voir aussi la &lt;a class=&quot;pagelink&quot; href=&quot;Svirfneblin.html&quot; title=&quot;Svirfneblin&quot;&gt;fiche de cr&#233;ature&lt;/a&gt; d&#39;un svirfneblin standard.&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Dans les sombres profondeurs de la terre, les svirfneblins prot&#232;gent leurs enclaves et leurs petites communaut&#233;s des terreurs qui gisent dans les profondeurs oubli&#233;es de la lumi&#232;re. Cr&#233;atures s&#233;rieuses &#224; la peau gris ardoise, ces gnomes sont tr&#232;s diff&#233;rents de leurs cousins de la surface : ils ont choisi de vivre dans les myst&#233;rieuses entrailles du monde et de prot&#233;ger la surface des ignobles cr&#233;atures qui partagent leurs grottes, leurs cryptes et leurs tunnels.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TRAITSSTANDARDS&quot; href=&quot;#TRAITSSTANDARDS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Traits raciaux standards&lt;a class=&quot;headeranchor&quot; id=&quot;Traits_raciaux_standards_5&quot; href=&quot;#Traits_raciaux_standards_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div class=&quot;presentation arrondi ombre espaceliste&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;-2 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt;, +2 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;, +2 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;, -4 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;.&lt;/b&gt; Les svirfneblins sont rapides et observateurs, mais relativement faibles et &#233;motionnellement d&#233;tach&#233;s.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Gnome.&lt;/b&gt; Les svirfneblins sont des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;humano&#239;des&lt;/a&gt; de sous-type &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Gnome.html&quot; title=&quot;Gnome (sous-type)&quot;&gt;gnome&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Taille P.&lt;/b&gt; Les svirfneblins sont des cr&#233;atures de &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures#Tableautailles.html&quot; title=&quot;taille P&quot;&gt;taille P&lt;/a&gt; qui re&#231;oivent un bonus de taille de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, un bonus de taille de +1 &#224; leurs &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;, un malus de -1 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bmo.html&quot; title=&quot;BMO&quot;&gt;BMO&lt;/a&gt; et au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt;, et un bonus de taille de +4 &#224; leurs tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Entra&#238;nement d&#233;fensif.&lt;/b&gt; Les svirfneblins re&#231;oivent un bonus d’esquive de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sens.&lt;/b&gt; Les svirfneblins ont la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 36 m&#232;tres ainsi que la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Chanceux.&lt;/b&gt; Les svirfneblins re&#231;oivent un bonus racial de +2 &#224; tous leurs &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tent.&lt;/b&gt; Les svirfneblins re&#231;oivent un bonus racial de +2 &#224; leurs tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; qui devient un bonus de +4 sous terre. Ils re&#231;oivent un bonus racial de +2 &#224; leurs tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (alchimie) et de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Haine.&lt;/b&gt; Les svirfneblins re&#231;oivent un bonus de +1 &#224; leurs &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; contre les cr&#233;atures &lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;humano&#239;des&lt;/a&gt; de sous-type &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Reptilien.html&quot; title=&quot;Reptilien (sous-type)&quot;&gt;reptilien&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Nain.html&quot; title=&quot;Nain (sous-type)&quot;&gt;nain&lt;/a&gt; gr&#226;ce &#224; leur entra&#238;nement contre ces ennemis d&#233;test&#233;s.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Connaissance de la pierre.&lt;/b&gt; Les svirfneblins gagnent &lt;a class=&quot;pagelink&quot; href=&quot;Nain.html#TRAITSSTANDARD&quot; title=&quot;Les nains&quot;&gt;connaissance de la pierre&lt;/a&gt;, comme les nains.&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;sistance &#224; la magie.&lt;/b&gt; Les svirfneblins ont une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt; &#233;gale &#224; 11 + leur niveau de personnage.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Magie des svirfneblins.&lt;/b&gt; Les svirfneblins ajoutent +1 au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de tous les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; des sorts d’&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Illusion.html&quot; title=&quot;Illusion&quot;&gt;illusion&lt;/a&gt; qu’ils lancent. Ils gagnent &#233;galement les &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Magiques-(Capacit&#233;).html&quot; title=&quot;Pouvoirs magiques (Mag)&quot;&gt;pouvoirs magiques&lt;/a&gt; suivants : Constant – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antid&#233;tection.html&quot; title=&quot;Antid&#233;tection&quot;&gt;antid&#233;tection&lt;/a&gt;&lt;/i&gt; ; 1/jour – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;C&#233;cit&#233;surdit&#233;.html&quot; title=&quot;C&#233;cit&#233;/surdit&#233;&quot;&gt;c&#233;cit&#233;/surdit&#233;&lt;/a&gt;&lt;/i&gt; (DD 12 + modificateur de Charisme), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;d&#233;guisement&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flou.html&quot; title=&quot;Flou&quot;&gt;flou&lt;/a&gt;&lt;/i&gt; ; le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; est &#233;gal au niveau de personnage du svirfneblin.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues.&lt;/b&gt; Les svirfneblins commencent le jeu en parlant le gnome et le commun des profondeurs. Ceux qui ont une valeur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; &#233;lev&#233;e peuvent apprendre d’autres langues parmi celles-ci : aklo, commun, draconique, elfique, g&#233;ant, gobelin, nain, orque et terreux.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TRAITSALTERNATIFS&quot; href=&quot;#TRAITSALTERNATIFS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Traits raciaux alternatifs&lt;a class=&quot;headeranchor&quot; id=&quot;Traits_raciaux_alternatifs_6&quot; href=&quot;#Traits_raciaux_alternatifs_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Il est possible de choisir les traits raciaux suivants &#224; la place des traits raciaux existants des svirfneblins. Consultez votre MJ avant de prendre ces nouvelles options.&lt;br /&gt;&lt;br /&gt;&lt;u&gt;&lt;i&gt;Remplace &#171; chanceux &#187; :&lt;/i&gt;&lt;/u&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Bien portant.&lt;/b&gt; Le svirfneblin gagne un bonus de +4 &#224; ses jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;Les maladies&quot;&gt;maladies&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt;, y compris les maladies magiques. Ce trait racial remplace chanceux.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;u&gt;&lt;i&gt;Remplace &#171; comp&#233;tent &#187; et &#171; haine &#187; :&lt;/i&gt;&lt;/u&gt;
&lt;ul&gt;&lt;li&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Races de la mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea Races/Races de la mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;Guetteur impassible.&lt;/b&gt; Les svirfneblins sont d&#39;abord venus sur Golarion pour contrecarrer les plans des f&#233;es mal&#233;fiques. Ceux qui poursuivent toujours ce but, et qui vivent principalement dans les colonies dans les profondeurs de l&#39;Andoran, b&#233;n&#233;ficient d&#39;un bonus racial de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; contre les cr&#233;atures &lt;a class=&quot;pagelink&quot; href=&quot;Type-F&#233;e.html&quot; title=&quot;F&#233;e&quot;&gt;f&#233;eriques&lt;/a&gt; ainsi que d&#39;un bonus racial de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;effets mentaux&lt;/a&gt;. Ce trait racial remplace comp&#233;tent et haine.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;u&gt;&lt;i&gt;Remplace &#171; magie des svirneblins &#187; :&lt;/i&gt;&lt;/u&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Oracle de pierre.&lt;/b&gt; Le svirfneblin ajoute +1 au &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; de tous les sorts de &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;registre&lt;/a&gt; de la terre qu’il lance. Il gagne aussi les &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Magiques-(Capacit&#233;).html&quot; title=&quot;Pouvoirs magiques (Mag)&quot;&gt;pouvoirs magiques&lt;/a&gt; suivants : Constant – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antid&#233;tection.html&quot; title=&quot;Antid&#233;tection&quot;&gt;antid&#233;tection&lt;/a&gt;&lt;/i&gt; ; 1/jour – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fa&#231;onnage-De-La-Pierre.html&quot; title=&quot;Fa&#231;onnage de la pierre&quot;&gt;fa&#231;onnage de la pierre&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Magique.html&quot; title=&quot;Pierre magique&quot;&gt;pierre magique&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pierres-Comm&#232;res.html&quot; title=&quot;Pierres comm&#232;res&quot;&gt;pierres comm&#232;res&lt;/a&gt;&lt;/i&gt; ; le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; est &#233;gal au niveaux de classes du svirfneblin. Ce trait racial remplace magie des svirfneblins.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h2 class=&quot;separator&quot;&gt;Bonus alternatifs de classe de pr&#233;dilection&lt;a class=&quot;headeranchor&quot; id=&quot;Bonus_alternatifs_de_classe_de_pr&#233;dilection_7&quot; href=&quot;#Bonus_alternatifs_de_classe_de_pr&#233;dilection_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Chacune de ces r&#233;compenses remplace celle que les joueurs obtenaient normalement en gagnant un niveau dans une &lt;a class=&quot;pagelink&quot; href=&quot;Progression-Des-Personnages.html#CLASSEDEPREDILECTION&quot; title=&quot;Progression des personnages&quot;&gt;classe de pr&#233;dilection&lt;/a&gt;, &#224; savoir 1 point de vie suppl&#233;mentaire ou 1 rang de comp&#233;tence suppl&#233;mentaire. Contrairement &#224; ces r&#233;compenses d’ordre g&#233;n&#233;rique, les r&#233;compenses alternatives se focalisent sur les sp&#233;cificit&#233;s de la classe et sur les tendances g&#233;n&#233;rales d’une race.&lt;br /&gt;&lt;br /&gt;Le personnage choisit son option de classe de pr&#233;dilection quand il gagne un niveau. Ces avantages se cumulent toujours, sauf indication contraire.&lt;br /&gt;&lt;br /&gt;Enfin, &#224; chaque fois que le personnage les choisit, nombre d’avantages alternatifs ajoutent seulement +1/2, +1/3, +1/4 ou +1/6 (au lieu de +1) &#224; un jet ou &#224; une aptitude de classe (comme un ajout au nombre de rages sanguines quotidiennes du sanguin ou au total de points de panache du bretteur). Quand le personnage applique cet avantage &#224; un jet de d&#233;, il arrondit toujours &#224; l’inf&#233;rieur (0 au minimum). Il devra donc en choisir certains &#224; plusieurs reprises avant d’en tirer le moindre b&#233;n&#233;fice.&lt;br /&gt;&lt;br /&gt;Certaines options s’accompagnent d’une limite num&#233;raire fixe, une fois cette limite atteinte, il ne sert plus &#224; rien de choisir l’option qui n’a pas d’effet suppl&#233;mentaire. Le personnage peut toujours choisir une r&#233;compense ordinaire quand il gagne un niveau dans sa classe de pr&#233;dilection (&#224; savoir 1 point de vie ou 1 rang de comp&#233;tence suppl&#233;mentaire).&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Alchimiste&lt;/a&gt;.&lt;/b&gt; L&#39;alchimiste rajoute une formule d’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#EXTRAITS&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;extrait&lt;/a&gt; issue de la &lt;a class=&quot;pagelink&quot; href=&quot;Liste-Des-Formules-Dalchimiste.html&quot; title=&quot;Liste des formules d&amp;#39;alchimiste&quot;&gt;liste des formules d’alchimiste&lt;/a&gt; &#224; son livre de formules. Cette formule doit &#234;tre d’au moins un niveau de moins que la formule la plus puissante qu’il conna&#238;t. &lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oracle.html&quot; title=&quot;L&amp;#39;oracle&quot;&gt;Oracle&lt;/a&gt;.&lt;/b&gt; L&#39;oracle rajoute un sort connu issu de la &lt;a class=&quot;pagelink&quot; href=&quot;Liste-Des-Sorts-De-Pr&#234;tres.html&quot; title=&quot;Liste des sorts de pr&#234;tre/pr&#234;tre combattant/oracle&quot;&gt;liste des sorts d’oracle&lt;/a&gt;. Ce sort doit &#234;tre inf&#233;rieur d’au moins un niveau au sort de plus haut niveau que peut lancer l’oracle.
&lt;/td&gt;&lt;td width=&quot;1%&quot;&gt;
&lt;td style=&quot;border-left:1px solid #4b3124&quot; width=&quot;1%&quot;&gt;&lt;/td&gt;
&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;R&#244;deur&lt;/a&gt;.&lt;/b&gt; Le r&#244;deur rajoute une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 1/magique &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PACTEDUCHASSEUR&quot; title=&quot;Le r&#244;deur&quot;&gt;compagnon animal&lt;/a&gt;. Chaque fois que le r&#244;deur choisit cet avantage, la RD/magique augmente de +1/2 (RD maximum 10/magique). Si jamais le r&#244;deur remplace son compagnon animal, le nouveau compagnon b&#233;n&#233;ficie de cette RD.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Nouvelles r&#232;gles raciales&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_r&#232;gles_raciales_8&quot; href=&quot;#Nouvelles_r&#232;gles_raciales_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Voici les options accessibles aux svirfneblins, d’autres races adapt&#233;es peuvent s’en servir si le MJ donne son accord.
&lt;h3 class=&quot;separator&quot;&gt;Dons&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_0&quot; href=&quot;#Dons_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les svirfneblins ont acc&#232;s &#224; ce don.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;25%&quot;&gt;&amp;nbsp;&lt;/td&gt;&lt;td WIDTH= &quot;6%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;25%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;44%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pose-Sto&#239;que.html&quot; title=&quot;Pose sto&#239;que&quot;&gt;Pose sto&#239;que&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Svirfneblin-(Race).html&quot; title=&quot;Les svirfneblins&quot;&gt;svirfneblin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Au bout de 5 rounds d&#39;immobilit&#233;, le svirfneblin se fond dans le d&#233;cor&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
&lt;div class=&quot;row ligne&quot; style=&quot;&quot;&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;Arch&#233;types de classes&lt;a class=&quot;headeranchor&quot; id=&quot;Arch&#233;types_de_classes_1&quot; href=&quot;#Arch&#233;types_de_classes_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Cet arch&#233;type de classe est accessible aux svirfneblins :
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artificier-Des-Profondeurs-(Alchimiste).html&quot; title=&quot;Artificier des profondeurs&quot;&gt;Artificier des profondeurs (alchimiste)&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;couvertes d&#39;alchimiste&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;couvertes_dalchimiste_2&quot; href=&quot;#D&#233;couvertes_dalchimiste_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Tout alchimiste r&#233;pondant aux conditions requises indiqu&#233;es peut prendre ces nouvelles d&#233;couvertes, mais elles sont plus courantes pour les svirfneblins.
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEAECLATSDEVERRE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;Bombe &#224; &#233;clats de verre&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEDETENEBRES&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;Bombe de t&#233;n&#232;bres&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;&#201;quipement&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;quipement_3&quot; href=&quot;#&#201;quipement_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les svirfneblins ont acc&#232;s &#224; l’&#233;quipement suivant :
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;chette-De-Choc-(Arme).html&quot; title=&quot;Fl&#233;chette de choc&quot;&gt;Fl&#233;chette de choc&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sorts&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_4&quot; href=&quot;#Sorts_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les svirfneblins ont acc&#232;s &#224; ce sort :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nage-Dans-La-Terre.html&quot; title=&quot;Nage dans la terre&quot;&gt;Nage dans la terre&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(MR)&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Alch 4&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Chaman.html&quot; title=&quot;Le chaman&quot;&gt;Cham 4&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;Dru 4&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ens&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;Mag 4&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html&quot; title=&quot;Le sanguin&quot;&gt;San 4&lt;/a&gt;). Permet &#224; la cible de nager &#224; travers la pierre, la terre, et d&#39;autres terrains.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;/div&gt;
